def app_vue(s):
    s = s.replace('document.documentElement.setAttribute("data-theme", "dark"); // thème sombre verrouillé (identité noir & or)',
                  'const t = localStorage.getItem("pb_theme") === "light" ? "light" : "dark"; // sombre par défaut\n  document.documentElement.setAttribute("data-theme", t);\n  document.documentElement.style.colorScheme = t;')
    return s
