def ctrl(s):
    s = s.replace("return { id: user.id, firstName: user.firstName, lastName: user.lastName, email: user.email, role: user.role, phone: user.phone };",
                  "return { id: user.id, firstName: user.firstName, lastName: user.lastName, email: user.email, role: user.role, phone: user.phone, address: user.address, city: user.city, createdAt: user.createdAt, hasPassword: Boolean(user.passwordHash) };")
    if "export async function updateMe" not in s:
        s = s.rstrip("\n") + '''

/** Mise à jour du profil (nom, téléphone, adresse, ville). L'email et le rôle ne sont jamais modifiables ici. */
export async function updateMe(req, res) {
  const { firstName, lastName, phone, address, city } = req.body;
  const user = await prisma.user.update({
    where: { id: req.user.sub },
    data: { firstName, lastName, phone: phone || null, address: address || null, city: city || "Abidjan" },
  });
  res.json(publicUser(user));
}
'''
    return s
rw("backend/src/controllers/auth.controller.js", ctrl)

def validator(s):
    if "updateProfileSchema" in s: return s
    return s.rstrip("\n") + '''

export const updateProfileSchema = z.object({
  firstName: z.string().trim().min(1, "Prénom requis").max(80),
  lastName: z.string().trim().min(1, "Nom requis").max(80),
  phone: z.string().trim().max(20).regex(/^[0-9+\\s().-]*$/, "Numéro invalide").optional().or(z.literal("")),
  address: z.string().trim().max(200).optional().or(z.literal("")),
  city: z.string().trim().max(80).optional().or(z.literal("")),
}).strict();
'''
rw("backend/src/validators/auth.validator.js", validator)

def routes(s):
    if "updateMe" in s: return s
    s = s.replace("googleAuth, changePassword }", "googleAuth, changePassword, updateMe }")
    s = s.replace("loginSchema, changePasswordSchema }", "loginSchema, changePasswordSchema, updateProfileSchema }")
    s = s.replace('router.get("/me", requireAuth, me);', 'router.get("/me", requireAuth, me);\nrouter.patch("/me", requireAuth, validateBody(updateProfileSchema), updateMe);')
    return s
rw("backend/src/routes/auth.routes.js", routes)

def orders_ctrl(s):
    return s.replace("include: { items: true },\n    orderBy: { createdAt: \"desc\" },", "include: { items: true, payment: true },\n    orderBy: { createdAt: \"desc\" },")
rw("backend/src/controllers/orders.controller.js", orders_ctrl)
